import React from 'react';
import './whyUs.css';


async function getWhyUsData() {
  const res = await fetch('/api/whyus');
  return res.json();
}

export default async function WhyUs() {
  const items: [] = await getWhyUsData();

  return (
    <section id="why-us" className="why-us">

    </section>
  );
}